arguments.old_text:
def _translate_index(self, index):
    if index < 0:
        index += len(self)
    rel_idx, lists = index, self.lists
    for list_idx in range(len(lists)):
        len_list = len(lists[list_idx])
        if rel_idx < len_list:
            break
        rel_idx -= len_list
    if rel_idx < 0:
        return None, None
    return list_idx, rel_idx

arguments.new_text:
def _translate_index(self, index):
    if index < 0:
        index += len(self)
        if index < 0:
            return None, None
    rel_idx, lists = index, self.lists
    for list_idx in range(len(lists)):
        len_list = len(lists[list_idx])
        if rel_idx < len_list:
            break
        rel_idx -= len_list
    else:
        # index ran past the end (e.g. index == len(self)); there is
        # no element at this position, so signal out-of-range.
        return None, None
    return list_idx, rel_idx

