from boltons.listutils import BarrelList

def mk(n=20, split=True):
    b = BarrelList(range(n))
    if split:
        b._size_factor = 1
        b.lists = [b.lists[0][:1], b.lists[0][1:]] if len(b.lists)==1 else b.lists
        # force balancing/splitting
        for i in range(50):
            b.insert(0, -i)
    return b

# boundary indexing
for split in (False, True):
    for n in (0,1,5,20):
        bl = BarrelList(range(n))
        if split and n:
            bl._size_factor = 1
            for i in range(40):
                bl.append(i+n)
        # compare against builtin
        for idx in list(range(-len(bl)-2, len(bl)+2)):
            got=blidx=None
            try: got = bl[idx]
            except IndexError: got='IE'
            try: blidx = list(bl)[idx]
            except IndexError: blidx='IE'
            assert got==blidx, (split,n,idx,got,blidx)
print('indexing ok')

# insert boundaries
for split in (False, True):
    for n in (0,1,5,20):
        for idx in range(-len(list(range(n)))-2, n+3):
            ref=list(range(n)); bl=BarrelList(range(n))
            if split and n:
                bl._size_factor=1
                for i in range(40): bl.append(i)
                ref=ref+list(range(40))
            ref.insert(idx,'X'); bl.insert(idx,'X')
            assert list(bl)==ref, (split,n,idx,list(bl),ref)
print('insert ok')

# del slices
import itertools
for split in (False, True):
    for n in (0,1,5,10):
        starts=[None,-12,-1,0,1,5,9,10,12,100]
        stops=[None,-12,-1,0,1,5,9,10,12,100]
        for s in starts:
            for e in stops:
                ref=list(range(n)); bl=BarrelList(range(n))
                if split and n:
                    bl._size_factor=1
                    for i in range(30): bl.append(i+100)
                    ref=ref+list(range(100,130))
                del ref[s:e]
                del bl[s:e]
                assert list(bl)==ref, (split,n,s,e,list(bl),ref)
print('del slice ok')

