import random
from boltons.setutils import IndexedSet

class Ref:
    def __init__(self, it=()):
        self.l=[]
        for x in it:
            if x not in self.l: self.l.append(x)
    def discard(self,x):
        if x in self.l: self.l.remove(x)

random.seed(0)
for trial in range(3000):
    n=random.randint(0,30)
    base=list(range(n)); random.shuffle(base)
    s=IndexedSet(base)
    r=Ref(base)
    for step in range(random.randint(1,10)):
        k=random.randint(0,n)
        vals=random.sample(range(n),k) if n>=k else []
        op=random.choice(['diff','inter','xor','update'])
        if op=='diff':
            s.difference_update(vals)
            for v in vals: r.discard(v)
        elif op=='inter':
            s.intersection_update(vals)
            r.l=[x for x in r.l if x in set(vals)]
        elif op=='update':
            s.update(vals)
            for v in vals:
                if v not in r.l: r.l.append(v)
        else:
            s.symmetric_difference_update(vals)
            for v in vals:
                if v in r.l: r.l.remove(v)
                else: r.l.append(v)
        if list(s)!=r.l:
            print('MISMATCH', trial, step, op, base, vals)
            print('got', list(s))
            print('exp', r.l)
            raise SystemExit
        for i,x in enumerate(r.l):
            if s.index(x)!=i or s[i]!=x:
                print('IDX MISMATCH', trial, op, base, vals, i, x)
                print('got', list(s), [s.index(y) for y in s])
                print('exp', r.l)
                raise SystemExit
print('all ok')
"

