import random
from boltons.setutils import IndexedSet

def check(s, model, ctx):
    if list(s) != model:
        print("ORDER MISMATCH", ctx, list(s), model); return False
    for i, v in enumerate(model):
        if s[i] != v:
            print("INDEX MISMATCH", ctx, i, s[i], v, model); return False
        if s.index(v) != i:
            print("INDEX() MISMATCH", ctx, i, s.index(v), model); return False
    return True

for seed in range(300):
    random.seed(seed)
    s = IndexedSet()
    model = []
    for step in range(80):
        op = random.choice(['add','discard','diff','inter','pop'])
        if op == 'add':
            v = random.randrange(30)
            s.add(v)
            if v not in model: model.append(v)
        elif op == 'discard':
            v = random.randrange(30)
            s.discard(v)
            if v in model: model.remove(v)
        elif op == 'diff':
            others = [set(random.sample(range(30), random.randrange(0,8))) for _ in range(random.randrange(1,3))]
            s.difference_update(*others)
            rem = set().union(*others) if others else set()
            model = [v for v in model if v not in rem]
        elif op == 'inter':
            others = [set(random.sample(range(30), random.randrange(0,10))) for _ in range(random.randrange(1,3))]
            s.intersection_update(*others)
            keep = set(model).intersection(*others)
            model = [v for v in model if v in keep]
        elif op == 'pop' and model:
            i = random.randrange(len(model))
            got = s.pop(i)
            exp = model.pop(i)
            if got != exp:
                print("POP MISMATCH", seed, step, i, got, exp); raise SystemExit
        if not check(s, model, (seed, step, op)):
            raise SystemExit
print("all ok")
EOF

